// RUN: %clang_cc1 -triple x86_64-unknown-linux-gnu -O2 -fopenmp -debug-info-kind=limited -mllvm -openmp-opt-disable -emit-llvm -o - %s | sed -n '/^define internal /,/^}/p' | FileCheck %s

// Captured automatic storage remains alive across the synchronous parallel
// call. Preserve that fact without asserting noalias: its address may escape,
// and its value may change. Pointer values stored in it have no such guarantee.
extern bool enabled[64];
extern "C" void opaque() noexcept;
extern "C" void consume(double) noexcept;

// The capture-slot load can move out of the conditional loop.
extern "C" void pointer_capture(double *values) {
#pragma omp parallel
  {
    opaque();
    double sum = 0;
    for (int i = 0; i < 64; ++i)
      if (enabled[i])
        sum += values[i];
    consume(sum);
  }
}

// A shared scalar also passes the address of automatic storage.
extern "C" void scalar_capture(double value) {
#pragma omp parallel
  consume(value);
}

// An escaped slot remains alive, but opaque() can change its contents.
double **escaped;
extern "C" void escaped_capture(double *values) {
  escaped = &values;
#pragma omp parallel
  for (int i = 0; i < 64; ++i) {
    opaque();
    if (enabled[i])
      consume(values[i]);
  }
}

// A reference may name heap storage freed by opaque().
extern "C" void reference_capture(double *&values) {
#pragma omp parallel
  {
    opaque();
    if (enabled[0])
      consume(values[0]);
  }
}

// A firstprivate pointer is the pointee address, not a capture-slot address.
extern "C" void firstprivate_capture(double *values) {
#pragma omp parallel firstprivate(values)
  {
    opaque();
    if (enabled[0])
      consume(values[0]);
  }
}

// Serialized parallel regions provide the same lifetime guarantee.
extern "C" void serialized_capture(double *values) {
#pragma omp parallel if(0)
  consume(values[0]);
}
